 * @param {string} channel
 * @returns {string}
 */
export function normalizeArchiveChannel(channel) {
 const s = String(channel ?? '').trim();
 if (s === '') return '';
 if (s.startsWith('wechat-group:')) return `wechat:group:${s.slice('wechat-group:'.length)}`;
 if (s.startsWith('wechat-private:')) return `wechat:private:${s.slice('wechat-private:'.length)}`;
 const m = /^wechat:(private|group):([\s\S]+)$/i.exec(s);
 if (m) return `wechat:${m[1].toLowerCase()}:${m[2]}`;
 return s;
}

