/**
 * 微信身份映射（第一阶段）：`person_wechat_alias.wechat_id → person.canonical_id`。
 * 照 `person_qq_alias` 的样子单独一张表，不动 person 表结构。
 * @param {import('node:sqlite').DatabaseSync} db
 * @param {string} wechatId 微信侧稳定的 id（如 853200206）
 * @returns {string|null} canonical_id，没有映射就是 null
 */
export function canonicalOfWechat(db, wechatId) {
	const id = String(wechatId ?? '').trim();
	if (id === '') return null;
	const row = db.prepare('SELECT canonical_id FROM person_wechat_alias WHERE wechat_id = ?').get(id);
	return row ? String(row.canonical_id) : null;
}

/** 微信 id → person 行（没有映射 / 人没了都返回 null，不新建）。 */
export function findPersonByWechat(db, wechatId) {
	const cid = canonicalOfWechat(db, wechatId);
	if (cid === null) return null;
	return db.prepare('SELECT * FROM person WHERE canonical_id = ?').get(cid) ?? null;
}

/** 写/改一条微信身份映射（幂等，重复写同一个 wechat_id 就改指向）。 */
export function setWechatAlias(db, wechatId, canonicalId) {
	const id = String(wechatId ?? '').trim();
	const cid = String(canonicalId ?? '').trim();
	if (id === '' || cid === '') throw new Error('微信身份映射需要 wechat_id 和 canonical_id');
	db.prepare('INSERT INTO person_wechat_alias (wechat_id, canonical_id) VALUES (?, ?) ON CONFLICT(wechat_id) DO UPDATE SET canonical_id = excluded.canonical_id')
		.run(id, cid);
	return { wechatId: id, canonicalId: cid };
}

/**
 * 微信身份认人（全同步口径：微信私聊与群内发言者都建 person，好感 / 记忆跨渠道共用同一份）。
 *
 * 规则：
 *  - `person_wechat_alias` 里有登记的 → 用那条映射指向的 person，并把这次互动记上去；
 *  - 没登记 → 新建一个只有微信别名的 person（p_xxxxxxxx）并把映射补登记（下次认得出）；
 *  - 映射指向 canonical_id='master' 但 person 行不见了（被手删过）→ 补建 master 行。
 *
 * ⚠️ 微信 id 一律是「微信侧稳定 id」（WechatAgent 传来的 conversation_id / sender_id），
 *    **绝不能**拿去当 QQ 号查 person —— 那是两个完全无关的号段（QQ 412205303 vs 微信 853200206）。
 *
 * @param {import('node:sqlite').DatabaseSync} db
 * @param {{ wechatId: string, nickname?: string, nowMs: number }} p
 * @returns {object|null} person 行；wechatId 为空时返回 null（认不出人，调用方别记到别人名下）
 */
export function resolveOrCreateWechatPerson(db, { wechatId, nickname, nowMs }) {
	const id = String(wechatId ?? '').trim();
	if (id === '') return null;
	const name = String(nickname ?? '').trim();
	// 纯微信身份（没有 QQ / B站 / 抖音号、也不是 master）才跟着微信昵称改名；
	// 已经和 QQ 等拼起来的人保留原来的称呼，免得微信昵称把主人叫成别人。
	const touch = (canonicalId) => {
		db.prepare(`
			UPDATE person SET interaction_count = interaction_count + 1, last_seen_at = ?,
			  display_name = CASE WHEN canonical_id <> 'master' AND qq_uin IS NULL AND bili_uid IS NULL AND douyin_uid IS NULL
			                      AND ? <> '' THEN ? ELSE display_name END
			WHERE canonical_id = ?
		`).run(nowMs, name, name, canonicalId);
		return db.prepare('SELECT * FROM person WHERE canonical_id = ?').get(canonicalId) ?? null;
	};
	db.exec('BEGIN');
	try {
		const cid = canonicalOfWechat(db, id);
		let row = cid === null ? null : touch(cid);
		if (row === null && cid === 'master') row = ensureMasterPerson(db, nowMs);
		if (row === null) {
			const newCid = randomCanonicalId();
			db.prepare(`
				INSERT INTO person (canonical_id, display_name, relation_stage, interaction_count, first_seen_at, last_seen_at)
				VALUES (?, ?, 'stranger', 1, ?, ?)
			`).run(newCid, name || id, nowMs, nowMs);
			setWechatAlias(db, id, newCid);
			row = db.prepare('SELECT * FROM person WHERE canonical_id = ?').get(newCid);
		}
		db.exec('COMMIT');
		return row;
	} catch (error) {
		db.exec('ROLLBACK');
		throw error;
	}
}

